import{_ as o,a as n,c as a,ac as t}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · 单元 2 语法总结 · 非限定性定语从句至反身代词与相互代词","description":"L21–L40 规则、例句、易错点。","frontmatter":{"title":"第三册：培养技能 · 单元 2 语法总结 · 非限定性定语从句至反身代词与相互代词","description":"L21–L40 规则、例句、易错点。","splitFrom":"life/english/new-concept/book-3/unit-02/grammar.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第三册：培养技能 · 单元 2 语法总结","summary":"L21–L40 规则、例句、易错点。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · 单元 2 语法总结 · 完成时不定式的先后关系至情态动词加完成式推断","link":"/life/english/new-concept/book-3/unit-02/grammar-part-01"},"next":{"text":"第三册：培养技能 · 单元 2 单词与短语","link":"/life/english/new-concept/book-3/unit-02/vocabulary"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · 单元 2 语法总结 · 完成时不定式的先后关系至情态动词加完成式推断","link":"/life/english/new-concept/book-3/unit-02/grammar-part-01"},"next":{"text":"第三册：培养技能 · 单元 2 单词与短语","link":"/life/english/new-concept/book-3/unit-02/vocabulary"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-02/grammar-part-02.md","filePath":"life/english/new-concept/book-3/unit-02/grammar-part-02.md"}'),s={name:"life/english/new-concept/book-3/unit-02/grammar-part-02.md"};function r(i,e,l,h,p,c){return n(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="第三册-培养技能-·-单元-2-语法总结-·-非限定性定语从句至反身代词与相互代词" tabindex="-1">第三册：培养技能 · 单元 2 语法总结 · 非限定性定语从句至反身代词与相互代词 <a class="header-anchor" href="#第三册-培养技能-·-单元-2-语法总结-·-非限定性定语从句至反身代词与相互代词" aria-label="Permalink to &quot;第三册：培养技能 · 单元 2 语法总结 · 非限定性定语从句至反身代词与相互代词&quot;">​</a></h1><p><a href="/life/english/new-concept/book-3/unit-02/grammar">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-3/unit-02/overview">单元导读</a> · <a href="/life/english/new-concept/book-3/unit-02/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-3/unit-02/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-3/unit-02/review">单元复习与自测</a></p><h2 id="非限定性定语从句" tabindex="-1">非限定性定语从句 <a class="header-anchor" href="#非限定性定语从句" aria-label="Permalink to &quot;非限定性定语从句 {#非限定性定语从句}&quot;">​</a></h2><p>非限定性定语从句用逗号与主句隔开，补充而不负责筛选指代对象。指人常用 who，指物用 which，表示所属用 whose，不能用 that，关系词也不能省略。限定性与非限定性的区别不是单纯停顿：my neighbours who cycle 指骑车的那部分邻居，my neighbours, who cycle, 对当前提到的全部邻居补充骑车信息。写人物简介时，名字已经明确身份，补充经历往往适合非限定从句，但仍要看是否存在同名或范围限制。</p><p><strong>L31 原创例句：</strong> Mr Vale, who repairs clocks for fun, keeps a tiny workshop in his kitchen.</p><p>韦尔先生以修钟为乐，他在厨房里设有一个小工作区。</p><p><strong>易错：</strong> Mr Vale, that repairs clocks, ... 不符合非限定从句规则，应使用 who，并补足完整主句。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-031">Lesson 31</a></p><h2 id="现在完成时被动" tabindex="-1">现在完成时被动 <a class="header-anchor" href="#现在完成时被动" aria-label="Permalink to &quot;现在完成时被动 {#现在完成时被动}&quot;">​</a></h2><p>has 或 have been 加过去分词表示到现在为止已经完成、且与现在相关的被动动作。主语单数用 has，复数用 have；been 不能省略，否则可能变成主动完成时。现在完成时通常不与明确结束的过去时间如 yesterday 直接搭配，若给出具体过去时间应改用过去时。报告研究进展时，has been identified 表示已识别，has not yet been identified 表示仍未完成，不能因整句含有完成时就误认为所有问题都已解决。</p><p><strong>L32 原创例句：</strong> Three wooden beams have been recovered, but the vessel has not yet been identified.</p><p>三根木梁已被打捞出来，但船只身份尚未确认。</p><p><strong>易错：</strong> The wreck has discovered 缺少被动的 been，应为 has been discovered；若由研究者主动发现，则主语需改为 researchers。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-032">Lesson 32</a></p><h2 id="否定副词前置倒装" tabindex="-1">否定副词前置倒装 <a class="header-anchor" href="#否定副词前置倒装" aria-label="Permalink to &quot;否定副词前置倒装 {#否定副词前置倒装}&quot;">​</a></h2><p>never、rarely、seldom 等否定或近否定副词放在句首时，通常触发部分倒装，即助动词置于主语前。原句没有助动词时，根据时态加入 do、does 或 did，实义动词恢复原形。Never had I seen ... 把完成时的 had 前移。倒装主要用于较正式或强调性表达，不必每段都使用。not until 引导状语置前时，倒装发生在主句而非 until 从句；若否定词不位于句首，通常保持普通语序。</p><p><strong>L33 原创例句：</strong> Never had I seen the station so quiet before that morning.</p><p>在那个早晨之前，我从未见过车站如此安静。</p><p><strong>易错：</strong> Never I saw ... 缺少倒装；一般过去时应写 Never did I see ...，不能写 did I saw。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-033">Lesson 33</a></p><h2 id="分词状语的逻辑主语" tabindex="-1">分词状语的逻辑主语 <a class="header-anchor" href="#分词状语的逻辑主语" aria-label="Permalink to &quot;分词状语的逻辑主语 {#分词状语的逻辑主语}&quot;">​</a></h2><p>现在分词短语可表示与主句同时的动作、原因或伴随情况，通常要求其逻辑主语与主句主语一致。Opening the drawer, I found ... 表示打开抽屉的是 I。若主句改为 a letter appeared，就可能让句面上变成信件打开抽屉。完成式 having done 强调分词动作先完成，但时间顺序已明确时不必机械使用。分词短语会压缩逻辑关系，若读者难以判断是原因还是时间，保留 when 或 because 从句往往更清楚。</p><p><strong>L34 原创例句：</strong> Looking beneath the frame, Maya noticed a small handwritten label.</p><p>玛雅查看画框下方时，注意到一张小小的手写标签。</p><p><strong>易错：</strong> Looking under the table, a coin appeared 容易构成悬垂分词；应改为 I found a coin 或 When I looked ...。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-034">Lesson 34</a></p><h2 id="情态动词的被动结构" tabindex="-1">情态动词的被动结构 <a class="header-anchor" href="#情态动词的被动结构" aria-label="Permalink to &quot;情态动词的被动结构 {#情态动词的被动结构}&quot;">​</a></h2><p>情态动词加 be 再加过去分词可表示某事应当、必须或可能被做，例如 should be reviewed。情态词后 be 保持原形，不随主语变化。must be done 强调必要性，may be done 表示许可或可能，需看上下文；must have been done 则常对过去已发生的被动动作作推断。不要把 should be done 的建议当作已经完成的事实。讨论公平处理时，可先说明标准，再报告实际步骤，避免情态要求与结果报告混写。</p><p><strong>L35 原创例句：</strong> Both statements should be examined before a decision is announced.</p><p>作出并宣布决定之前，应当审查双方陈述。</p><p><strong>易错：</strong> The statements should examined 缺 be；should be examined 仍不表示审查已经完成。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-035">Lesson 35</a></p><h2 id="so-与-such-的结果结构" tabindex="-1">so 与 such 的结果结构 <a class="header-anchor" href="#so-与-such-的结果结构" aria-label="Permalink to &quot;so 与 such 的结果结构 {#so-与-such-的结果结构}&quot;">​</a></h2><p>so 后通常接形容词或副词，such 后通常接名词短语。单数可数名词常用 such a 加形容词加名词，如 such a strange meeting；so many 加复数名词、so much 加不可数名词则是数量结构。后接 that 从句可表示结果，但 that 有时在口语中省略。so ... that 不能与目的连词 so that 混为一谈。夸张性的日常概率词不等于计算结果，写说明文时应避免把感叹修辞当成统计证据。</p><p><strong>L36 原创例句：</strong> It was such an unexpected meeting that neither of us spoke for a moment.</p><p>这场相遇太出乎意料，我们两人一时都没说话。</p><p><strong>易错：</strong> so an unexpected meeting 位置错误；可写 such an unexpected meeting，或 the meeting was so unexpected。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-036">Lesson 36</a></p><h2 id="by、until-与时刻表现在时" tabindex="-1">by、until 与时刻表现在时 <a class="header-anchor" href="#by、until-与时刻表现在时" aria-label="Permalink to &quot;by、until 与时刻表现在时 {#by、until-与时刻表现在时}&quot;">​</a></h2><p>by 加时间表示不迟于该时刻，常与完成目标相关；until 表示动作或状态持续到某时刻。not until 表示直到那时才发生，不能与 by 简单互换。before 严格表示在某时间之前，by 通常包含截止点。表示固定时刻表时，一般现在时可以指将来，如 The train leaves at six，但临时个人安排常用现在进行时。写出时间后还应说明是列车离站、上车截止还是人员到达，避免同一数字承担不同事件。</p><p><strong>L37 原创例句：</strong> We must reach the platform by six, although the train does not leave until ten past.</p><p>我们必须六点前或六点整到站台，虽然列车六点十分才开。</p><p><strong>易错：</strong> Wait by six 不表示一直等到六点，持续等待应写 Wait until six；arrive until six 在此也不自然。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-037">Lesson 37</a></p><h2 id="目的不定式与-for-doing" tabindex="-1">目的不定式与 for doing <a class="header-anchor" href="#目的不定式与-for-doing" aria-label="Permalink to &quot;目的不定式与 for doing {#目的不定式与-for-doing}&quot;">​</a></h2><p>to do 常说明行为目的，即某人为了什么采取行动；for doing 常说明物品用途或某种功能。A tool for measuring 是测量工具，He used a tool to measure 说明他使用工具的目的。in order to 更明确地标出目的，否定写 in order not to。不是所有 for 加 ing 都表示目的，也可能表示原因或感谢对象，应根据动词搭配判断。讨论古物用途时，may have been used to ... 保留推断空间，不能将可能用途写成确定事实。</p><p><strong>L38 原创例句：</strong> The group marked a stone each evening to keep track of passing days.</p><p>这群人每天晚上在石头上做记号，以记录日子的推移。</p><p><strong>易错：</strong> a tool for measure 应为 a tool for measuring；目的不定式则是 used it to measure。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-038">Lesson 38</a></p><h2 id="不定式后置修饰与介词" tabindex="-1">不定式后置修饰与介词 <a class="header-anchor" href="#不定式后置修饰与介词" aria-label="Permalink to &quot;不定式后置修饰与介词 {#不定式后置修饰与介词}&quot;">​</a></h2><p>名词或不定代词后可接不定式说明待完成的动作，例如 a route to follow。若被修饰词在不定式中相当于介词宾语，通常须保留介词，如 a person to talk to、nothing to worry about。若动词本身可直接带宾语，则不另加介词，如 a book to read。某些地点词如 place 后的介词可因惯用结构省略，但不应据此随意删除所有介词。此类短语常带潜在动作或用途，不能简单当作已发生的过去事实。</p><p><strong>L39 原创例句：</strong> We had a reliable guide to consult and a marked path to follow.</p><p>我们有可靠向导可以咨询，也有标记清楚的小路可走。</p><p><strong>易错：</strong> I need someone to speak 应表达为 someone to speak to，若意思是“需要一个说话者”，则原结构可能有不同含义。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-039">Lesson 39</a></p><h2 id="反身代词与相互代词" tabindex="-1">反身代词与相互代词 <a class="header-anchor" href="#反身代词与相互代词" aria-label="Permalink to &quot;反身代词与相互代词 {#反身代词与相互代词}&quot;">​</a></h2><p>myself、yourself、himself 等反身代词可在主语与宾语指同一对象时使用，也可放在名词或句末强调本人。by oneself 常表示独自或不借助他人。each other 表示不同成员之间的相互动作，与 themselves 意义不同。They introduced themselves 是各自介绍自己，They introduced each other 是互相介绍对方。反身代词不能只为显得正式而代替普通宾格，例如 Please contact me 通常比 contact myself 更合适，除非有明确反身或强调语境。</p><p><strong>L40 原创例句：</strong> The two actors introduced themselves before they introduced each other to the director.</p><p>两位演员先介绍自己，然后向导演介绍了对方。</p><p><strong>易错：</strong> They looked at themselves 表示看自己，looked at each other 表示彼此对视，不能互换。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-040">Lesson 40</a></p>',63)])])}const g=o(s,[["render",r]]);export{u as __pageData,g as default};
